Use a **persisted idempotency key per logical payment**, reused across retries and subsequent calls. This requires a gateway that guarantees idempotent charges for the same key and payload.

The following uses Node.js built-in `fetch`; adapt the endpoint and response fields to your gateway.

```ts
import { setTimeout as sleep } from "node:timers/promises";

interface ChargeInput {
  amountMinor: number; // e.g. 1099 = $10.99
  currency: string;
  paymentMethodToken: string;
  idempotencyKey: string; // Persist with the payment before calling.
}

interface ChargeResult {
  id: string;
  status: string;
}

class UnknownChargeOutcomeError extends Error {
  constructor(cause: unknown) {
    super(
      "Charge outcome is unknown. Reconcile with the gateway or retry " +
        "with the same idempotency key and payload.",
      { cause },
    );
    this.name = "UnknownChargeOutcomeError";
  }
}

const transientCodes = new Set([
  "ECONNRESET",
  "ECONNREFUSED",
  "ETIMEDOUT",
  "EAI_AGAIN",
  "EPIPE",
  "UND_ERR_CONNECT_TIMEOUT",
  "UND_ERR_HEADERS_TIMEOUT",
  "UND_ERR_BODY_TIMEOUT",
  "UND_ERR_SOCKET",
]);

function isTransientNetworkError(error: unknown): boolean {
  if (!(error instanceof Error)) return false;
  if (error.name === "TimeoutError") return true;

  const code = (error as Error & { code?: string }).code;
  return (
    (code !== undefined && transientCodes.has(code)) ||
    (error.cause !== undefined && isTransientNetworkError(error.cause))
  );
}

export async function chargePayment(
  input: ChargeInput,
  config: { chargesUrl: string; apiKey: string },
): Promise<ChargeResult> {
  if (
    !Number.isSafeInteger(input.amountMinor) ||
    input.amountMinor <= 0 ||
    !/^[A-Z]{3}$/.test(input.currency) ||
    !input.paymentMethodToken ||
    !input.idempotencyKey.trim()
  ) {
    throw new Error("Invalid charge input");
  }

  // Serialize once so every attempt sends the identical payload.
  const body = JSON.stringify({
    amount: input.amountMinor,
    currency: input.currency,
    payment_method: input.paymentMethodToken,
  });

  const maxAttempts = 3;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      const response = await fetch(config.chargesUrl, {
        method: "POST",
        redirect: "error",
        headers: {
          Authorization: `Bearer ${config.apiKey}`,
          "Content-Type": "application/json",
          "Idempotency-Key": input.idempotencyKey,
        },
        body,
        signal: AbortSignal.timeout(5_000),
      });

      if (response.status === 503) {
        await response.body?.cancel();
        throw Object.assign(new Error("Gateway unavailable"), {
          code: "GATEWAY_503",
        });
      }

      // Other HTTP errors are not retried automatically.
      if (!response.ok) {
        await response.body?.cancel();
        throw new Error(`Gateway returned HTTP ${response.status}`);
      }

      // A lost or invalid success response can leave the outcome unknown.
      const result: unknown = await response.json();
      if (
        typeof result !== "object" ||
        result === null ||
        !("id" in result) ||
        typeof result.id !== "string" ||
        !("status" in result) ||
        typeof result.status !== "string"
      ) {
        throw new UnknownChargeOutcomeError("Invalid gateway response");
      }

      return { id: result.id, status: result.status };
    } catch (error) {
      const retryable =
        isTransientNetworkError(error) ||
        (error instanceof Error &&
          "code" in error &&
          error.code === "GATEWAY_503");

      if (!retryable) throw error;
      if (attempt === maxAttempts - 1) {
        throw new UnknownChargeOutcomeError(error);
      }

      // Bounded exponential backoff with jitter.
      await sleep(Math.random() * Math.min(2_000, 250 * 2 ** attempt));
    }
  }

  throw new Error("Unreachable");
}
```

Do not generate a new key after a timeout: the gateway may already have charged the customer. If the gateway lacks idempotency support, reconcile the payment before retrying.

This is an illustrative implementation; it has not been tested against a specific gateway.

