```ts
import { setTimeout as sleep } from "node:timers/promises";
import { performance } from "node:perf_hooks";

type Charge = {
  amountMinor: number; // Integer minor units, e.g. cents.
  currency: string;
  paymentMethodToken: string; // Token, never raw card details.
  idempotencyKey: string; // Persisted before the first attempt.
};

class GatewayHttpError extends Error {
  constructor(public readonly status: number) {
    super(`Payment gateway returned HTTP ${status}`);
  }
}

export class ChargeOutcomeUnknown extends Error {
  constructor(
    public readonly idempotencyKey: string,
    cause: unknown,
  ) {
    super("Charge outcome unresolved; reconcile using the same key", { cause });
  }
}

const transientCodes = new Set([
  "ECONNRESET",
  "ECONNREFUSED",
  "ETIMEDOUT",
  "EAI_AGAIN",
  "EPIPE",
  "UND_ERR_CONNECT_TIMEOUT",
  "UND_ERR_HEADERS_TIMEOUT",
  "UND_ERR_BODY_TIMEOUT",
  "UND_ERR_SOCKET",
]);

function isTransientNetworkError(error: unknown): boolean {
  if (!(error instanceof Error)) return false;
  if (error.name === "TimeoutError") return true;

  const cause = error.cause as { code?: string } | undefined;
  return !!cause?.code && transientCodes.has(cause.code);
}

function retryAfterMs(value: string | null): number {
  if (!value) return 0;
  if (/^\d+$/.test(value)) return Number(value) * 1_000;

  const date = Date.parse(value);
  return Number.isNaN(date) ? 0 : Math.max(0, date - Date.now());
}

export async function chargePayment(
  charge: Charge,
  config: { baseUrl: string; apiKey: string },
): Promise<unknown> {
  if (
    !Number.isSafeInteger(charge.amountMinor) ||
    charge.amountMinor <= 0 ||
    !/^[A-Z]{3}$/.test(charge.currency) ||
    !charge.paymentMethodToken ||
    !/^[A-Za-z0-9_-]{1,128}$/.test(charge.idempotencyKey)
  ) {
    throw new Error("Invalid charge input");
  }

  const endpoint = new URL("/charges", config.baseUrl);
  if (endpoint.protocol !== "https:" || !config.apiKey) {
    throw new Error("HTTPS gateway URL and API key are required");
  }

  // This function owns retries: three total attempts within 15 seconds.
  const deadline = performance.now() + 15_000;
  const body = JSON.stringify({
    amount: charge.amountMinor,
    currency: charge.currency,
    payment_method: charge.paymentMethodToken,
  });
  let lastError: unknown;

  for (let attempt = 0; attempt < 3; attempt++) {
    const remaining = Math.floor(deadline - performance.now());
    if (remaining <= 0) break;

    let response: Response;
    let responseBody: string;

    try {
      response = await fetch(endpoint, {
        method: "POST",
        redirect: "error",
        headers: {
          Authorization: `Bearer ${config.apiKey}`,
          "Content-Type": "application/json",
          "Idempotency-Key": charge.idempotencyKey,
        },
        body,
        signal: AbortSignal.timeout(Math.min(5_000, remaining)),
      });
      responseBody = await response.text();
    } catch (error) {
      // A lost response does not prove the charge failed.
      if (!isTransientNetworkError(error)) {
        throw new ChargeOutcomeUnknown(charge.idempotencyKey, error);
      }
      lastError = error;
      response = undefined!;
      responseBody = "";
    }

    if (response) {
      if (response.ok) {
        try {
          return JSON.parse(responseBody) as unknown;
        } catch (error) {
          throw new ChargeOutcomeUnknown(charge.idempotencyKey, error);
        }
      }

      if (response.status !== 503) {
        // No retries for declines, authentication errors, or other statuses.
        throw new GatewayHttpError(response.status);
      }
      lastError = new GatewayHttpError(503);
    }

    if (attempt === 2) break;

    const backoff = Math.random() * Math.min(2_000, 250 * 2 ** attempt);
    const delay = Math.max(
      backoff,
      retryAfterMs(response?.headers.get("retry-after") ?? null),
    );

    if (delay >= deadline - performance.now()) break;
    await sleep(delay);
  }

  throw new ChargeOutcomeUnknown(charge.idempotencyKey, lastError);
}
```

