Use a discriminated union so each status carries only its relevant data. Validate progress at construction because TypeScript’s `number` includes fractions and values outside 0–100.

```ts
declare const percentageBrand: unique symbol;
type Percentage = number & { readonly [percentageBrand]: true };

function percentage(value: number): Percentage {
  if (!Number.isInteger(value) || value < 0 || value > 100) {
    throw new RangeError("Progress must be an integer from 0 to 100");
  }
  return value as Percentage;
}

type ExportJob = { readonly id: string } & (
  | { readonly status: "queued" }
  | { readonly status: "processing"; readonly progress: Percentage }
  | { readonly status: "completed"; readonly downloadUrl: string }
  | { readonly status: "failed"; readonly errorMessage: string }
);

function assertNever(value: never): never {
  throw new Error(`Unexpected export status: ${JSON.stringify(value)}`);
}

function handleStatusUpdate(job: ExportJob): string {
  switch (job.status) {
    case "queued":
      return "Export is queued.";

    case "processing":
      return `Export is ${job.progress}% complete.`;

    case "completed":
      return `Download your export: ${job.downloadUrl}`;

    case "failed":
      return `Export failed: ${job.errorMessage}`;

    default:
      return assertNever(job);
  }
}

// Example
handleStatusUpdate({
  id: "export-123",
  status: "processing",
  progress: percentage(42),
});
```

The exhaustive switch produces a compile-time error if a new status is added without updating the handler. For API responses, validate the incoming data before treating it as `ExportJob`; a type assertion alone performs no runtime validation.

