```ts
type ExportStatus =
  | { readonly status: "queued" }
  | { readonly status: "processing"; readonly progress: number }
  | { readonly status: "completed"; readonly downloadUrl: string }
  | { readonly status: "failed"; readonly errorMessage: string };

type ExportJob = {
  readonly id: string;
  readonly state: ExportStatus;
};

function updateExportStatus(
  job: ExportJob,
  next: ExportStatus,
): ExportJob {
  if (
    next.status === "processing" &&
    (!Number.isInteger(next.progress) ||
      next.progress < 0 ||
      next.progress > 100)
  ) {
    throw new RangeError("Progress must be an integer from 0 to 100.");
  }

  // Replace the whole state so previous status fields don't linger.
  return { ...job, state: { ...next } };
}

// Usage
let job: ExportJob = {
  id: "export-123",
  state: { status: "queued" },
};

job = updateExportStatus(job, {
  status: "processing",
  progress: 45,
});

job = updateExportStatus(job, {
  status: "completed",
  downloadUrl: "https://example.com/exports/export-123.csv",
});
```

The union requires a download URL for completion and an error message for failure. The handler rejects fractional, out-of-range, and nonfinite progress.

