```js
import {
  SQSClient,
  ReceiveMessageCommand,
  DeleteMessageCommand,
} from "@aws-sdk/client-sqs";
import { setTimeout as sleep } from "node:timers/promises";

function required(name) {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is required`);
  return value;
}

function integer(name, fallback, min, max) {
  const value = Number(process.env[name] ?? fallback);
  if (!Number.isInteger(value) || value < min || value > max) {
    throw new Error(`${name} must be an integer between ${min} and ${max}`);
  }
  return value;
}

const queueUrl = required("QUEUE_URL");
const jobEndpoint = new URL(required("JOB_ENDPOINT"));
if (jobEndpoint.protocol !== "https:") {
  throw new Error("JOB_ENDPOINT must use HTTPS");
}

const jobTimeoutMs = integer("JOB_TIMEOUT_MS", 30_000, 1000, 300_000);
const shutdownMs = integer("SHUTDOWN_TIMEOUT_MS", 45_000, 1000, 600_000);

// Covers the receive request, job processing, deletion, and a safety margin.
const visibilitySeconds = Math.ceil(jobTimeoutMs / 1000) + 90;

const sqs = new SQSClient({
  region: required("AWS_REGION"),
  maxAttempts: 3,
});

const pollController = new AbortController();
const workController = new AbortController();

let stopping = false;
let shutdownTimer;
let exitCode = 0;

function log(level, event, fields = {}) {
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    level,
    event,
    ...fields,
  }));
}

function shutdown(reason, code = 0) {
  exitCode = Math.max(exitCode, code);
  if (stopping) return;

  stopping = true;
  log("info", "shutdown_started", { reason });
  pollController.abort(); // Interrupt polling/backoff; let current work drain.

  shutdownTimer = setTimeout(() => {
    log("error", "shutdown_deadline_exceeded");
    workController.abort();
    // Leave unfinished jobs unacknowledged for redelivery.
    process.exit(1);
  }, shutdownMs);
}

process.on("SIGTERM", () => shutdown("SIGTERM"));
process.on("SIGINT", () => shutdown("SIGINT"));

process.on("uncaughtException", (error) => {
  log("error", "uncaught_exception", { errorType: error.name });
  // After an uncaught exception, terminate rather than continue processing.
  process.exit(1);
});

process.on("unhandledRejection", () => {
  log("error", "unhandled_rejection");
  process.exit(1);
});

async function processJob(message, signal) {
  const job = JSON.parse(message.Body ?? "");

  if (
    !job ||
    typeof job !== "object" ||
    typeof job.id !== "string" ||
    !/^[A-Za-z0-9._:-]{1,128}$/.test(job.id)
  ) {
    throw new Error("Invalid job: expected a stable id");
  }

  // Replace this HTTP call with your business logic if appropriate.
  // The receiver must durably deduplicate this key and return success only
  // after committing the effect. Every I/O operation must honor signal.
  const response = await fetch(jobEndpoint, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "idempotency-key": job.id,
    },
    body: JSON.stringify(job),
    signal,
    redirect: "error",
  });

  try {
    if (!response.ok) {
      throw new Error(`Job endpoint returned HTTP ${response.status}`);
    }
  } finally {
    await response.body?.cancel();
  }
}

async function run() {
  let pollFailures = 0;

  log("info", "worker_started");

  while (!stopping) {
    let result;

    try {
      result = await sqs.send(
        new ReceiveMessageCommand({
          QueueUrl: queueUrl,
          MaxNumberOfMessages: 1,
          WaitTimeSeconds: 20,
          VisibilityTimeout: visibilitySeconds,
        }),
        {
          abortSignal: AbortSignal.any([
            pollController.signal,
            AbortSignal.timeout(30_000),
          ]),
        },
      );
      pollFailures = 0;
    } catch (error) {
      if (stopping) break;

      pollFailures++;
      log("error", "poll_failed", {
        errorType: error.name,
        consecutiveFailures: pollFailures,
      });

      // SDK retries individual requests; this backs off between failed polls.
      const capMs = Math.min(30_000, 500 * 2 ** Math.min(pollFailures, 6));
      await sleep(Math.floor(Math.random() * capMs), undefined, {
        signal: pollController.signal,
      }).catch((error) => {
        if (!stopping) throw error;
      });
      continue;
    }

    // A receive may complete concurrently with SIGTERM.
    // Do not start the returned job; its visibility will expire.
    if (stopping) break;

    for (const message of result.Messages ?? []) {
      try {
        await processJob(
          message,
          AbortSignal.any([
            workController.signal,
            AbortSignal.timeout(jobTimeoutMs),
          ]),
        );

        await sqs.send(
          new DeleteMessageCommand({
            QueueUrl: queueUrl,
            ReceiptHandle: message.ReceiptHandle,
          }),
          {
            abortSignal: AbortSignal.any([
              workController.signal,
              AbortSignal.timeout(10_000),
            ]),
          },
        );

        log("info", "job_completed", { messageId: message.MessageId });
      } catch (error) {
        // Never acknowledge failed or uncertain work.
        log("error", "job_failed", {
          messageId: message.MessageId,
          errorType: error.name,
        });

        if (error instanceof SyntaxError) {
          // Invalid JSON is retried and eventually handled by the queue DLQ.
        }
      }
    }
  }
}

try {
  await run();
} catch (error) {
  log("error", "worker_failed", { errorType: error.name });
  exitCode = 1;
} finally {
  clearTimeout(shutdownTimer);
  sqs.destroy();
  log("info", "worker_stopped", { exitCode });
  process.exitCode = exitCode;
}
```

