```js
import {
  SQSClient,
  ReceiveMessageCommand,
  DeleteMessageCommand,
} from "@aws-sdk/client-sqs";
import { setTimeout as sleep } from "node:timers/promises";
import { processJob } from "./jobs.mjs";

function integer(name, fallback, min, max) {
  const value = Number(process.env[name] ?? fallback);
  if (!Number.isInteger(value) || value < min || value > max) {
    throw new Error(`${name} must be an integer between ${min} and ${max}`);
  }
  return value;
}

const queueUrl = process.env.QUEUE_URL;
if (!queueUrl) throw new Error("QUEUE_URL is required");
if (new URL(queueUrl).protocol !== "https:") {
  throw new Error("QUEUE_URL must use HTTPS");
}

const jobTimeoutMs = integer("JOB_TIMEOUT_MS", 20_000, 1_000, 300_000);
const shutdownMs = integer("SHUTDOWN_MS", 25_000, 1_000, 600_000);
const visibilitySeconds = integer("VISIBILITY_SECONDS", 60, 1, 43_200);

// Budget for receiving, processing, and acknowledging a message.
if (visibilitySeconds * 1000 < jobTimeoutMs + 30_000) {
  throw new Error("VISIBILITY_SECONDS must exceed JOB_TIMEOUT_MS by 30 seconds");
}

const sqs = new SQSClient({
  // Credentials come from the SDK credential chain: use a workload role.
  maxAttempts: 3,
});

const log = (level, event, fields = {}) => {
  console.log(JSON.stringify({
    time: new Date().toISOString(),
    level,
    event,
    ...fields,
  }));
};

let stopping = false;
let pollController;
let activeJobController;
let shutdownTimer;

function stop(signal) {
  if (stopping) return;
  stopping = true;
  log("info", "shutdown_started", { signal });

  // Cancel long polling, but allow the current job to finish.
  pollController?.abort();

  shutdownTimer = setTimeout(() => {
    activeJobController?.abort(new Error("Shutdown deadline exceeded"));
    log("error", "shutdown_deadline_exceeded");
    // Do not acknowledge unfinished work. SQS will redeliver it.
    process.exit(1);
  }, shutdownMs);
}

process.on("SIGTERM", stop);
process.on("SIGINT", stop);

async function handleMessage(message) {
  const controller = new AbortController();
  activeJobController = controller;

  // Exit if a handler ignores cancellation. Continuing could let an expired
  // job overlap with another consumer after its visibility timeout.
  const timer = setTimeout(() => {
    controller.abort(new Error("Job deadline exceeded"));
    log("error", "job_deadline_exceeded", { messageId: message.MessageId });
    process.exit(1);
  }, jobTimeoutMs);

  try {
    const job = JSON.parse(message.Body ?? "");
    if (
      !job ||
      typeof job !== "object" ||
      Array.isArray(job) ||
      typeof job.id !== "string" ||
      !job.id.trim() ||
      typeof job.type !== "string"
    ) {
      throw new Error("Invalid job envelope");
    }

    await processJob(job, { signal: controller.signal });

    clearTimeout(timer);

    // Separate timeout so acknowledgement can finish during graceful shutdown.
    await sqs.send(
      new DeleteMessageCommand({
        QueueUrl: queueUrl,
        ReceiptHandle: message.ReceiptHandle,
      }),
      { abortSignal: AbortSignal.timeout(5_000) },
    );

    log("info", "job_completed", { messageId: message.MessageId });
  } catch (error) {
    // Retain the message for retry / dead-letter routing. Avoid logging bodies,
    // credentials, or handler error messages that may contain sensitive data.
    log("error", "job_failed", {
      messageId: message.MessageId,
      errorType: error?.name ?? "UnknownError",
    });
  } finally {
    clearTimeout(timer);
    activeJobController = undefined;
  }
}

async function main() {
  let pollFailures = 0;
  log("info", "worker_started");

  while (!stopping) {
    pollController = new AbortController();

    let response;
    try {
      response = await sqs.send(
        new ReceiveMessageCommand({
          QueueUrl: queueUrl,
          MaxNumberOfMessages: 1,
          WaitTimeSeconds: 20,
          VisibilityTimeout: visibilitySeconds,
        }),
        {
          abortSignal: AbortSignal.any([
            pollController.signal,
            AbortSignal.timeout(25_000),
          ]),
        },
      );
      pollFailures = 0;
    } catch (error) {
      if (stopping) break;

      pollFailures += 1;
      log("error", "poll_failed", {
        errorType: error?.name ?? "UnknownError",
        consecutiveFailures: pollFailures,
      });

      // Bound recovery; let the platform restart an unhealthy worker.
      if (pollFailures >= 8) throw new Error("Polling recovery exhausted");

      const cap = Math.min(30_000, 1_000 * 2 ** (pollFailures - 1));
      try {
        await sleep(Math.random() * cap, undefined, {
          signal: pollController.signal,
        });
      } catch (error) {
        if (!stopping) throw error;
      }
      continue;
    }

    // A receive may complete concurrently with shutdown. Leave its message
    // unacknowledged rather than starting new work.
    if (stopping) break;

    const message = response.Messages?.[0];
    if (message) await handleMessage(message);
  }
}

try {
  await main();
} catch (error) {
  log("error", "worker_failed", { errorType: error?.name ?? "UnknownError" });
  process.exitCode = 1;
} finally {
  clearTimeout(shutdownTimer);
  sqs.destroy();
  log("info", "worker_stopped");
}
```

