export function loadConfig(
  env: NodeJS.ProcessEnv = process.env,
): Readonly<Config> {
  const errors: string[] = [];

  function required(name: string): string {
    const value = env[name];
    if (!value || value.trim() === "") {
      errors.push(`${name} is required`);
      return "";
    }
    return value;
  }

  function endpoint(
    name: string,
    value: string,
    protocols: string[],
    forbidCredentials: boolean,
  ): string {
    if (!value) return value;

    try {
      const url = new URL(value);
      if (
        value !== value.trim() ||
        !protocols.includes(url.protocol) ||
        !url.hostname ||
        url.hash ||
        (forbidCredentials &&
          (url.username || url.password || url.search))
      ) {
        throw new Error();
      }
    } catch {
      errors.push(`${name} must be a valid supported endpoint`);
    }

    return value;
  }

  const rawPort = env.PORT ?? "3000";
  const port = Number(rawPort);
  if (
    !/^[0-9]+$/.test(rawPort) ||
    !Number.isInteger(port) ||
    port < 1 ||
    port > 65535
  ) {
    errors.push("PORT must be an integer between 1 and 65535");
  }

  // This implementation assumes PostgreSQL.
  const databaseUrl = endpoint(
    "DATABASE_URL",
    required("DATABASE_URL"),
    ["postgres:", "postgresql:"],
    false,
  );

  const externalApiUrl = endpoint(
    "EXTERNAL_API_URL",
    required("EXTERNAL_API_URL"),
    ["https:"],
    true,
  );

  const externalApiToken = required("EXTERNAL_API_TOKEN");
  if (
    externalApiToken &&
    !/^[A-Za-z0-9\-._~+/]+=*$/.test(externalApiToken)
  ) {
    errors.push("EXTERNAL_API_TOKEN must be a valid bearer token");
  }

  if (errors.length) {
    throw new Error(`Invalid configuration: ${errors.join("; ")}`);
  }

  return Object.freeze({
    port,
    databaseUrl,
    externalApiUrl,
    externalApiToken,
  });
