import { randomUUID } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";

interface RequestLog {
  event: "http_request";
  timestamp: string;
  requestId: string;
  method: string;
  statusCode: number | null;
  durationMs: number;
  outcome: "finished" | "aborted";
}

type LogSink = (entry: Readonly<RequestLog>) => void;

const methods = new Set([
  "GET", "HEAD", "POST", "PUT", "PATCH",
  "DELETE", "OPTIONS", "CONNECT", "TRACE",
]);

const stdoutSink: LogSink = (entry) => {
  process.stdout.write(`${JSON.stringify(entry)}\n`);
};

export function requestLogging(log: LogSink = stdoutSink) {
  return (
    req: IncomingMessage,
    res: ServerResponse,
    next: () => void,
  ): void => {
    const started = process.hrtime.bigint();
    const requestId = randomUUID();
    let logged = false;

    // Generate locally; do not trust incoming correlation headers.
    res.setHeader("X-Request-ID", requestId);

    function complete(outcome: RequestLog["outcome"]): void {
      if (logged) return;
      logged = true;

      res.off("finish", onFinish);
      res.off("close", onClose);

      const entry: RequestLog = {
        event: "http_request",
        timestamp: new Date().toISOString(),
        requestId,
        method: methods.has(req.method ?? "")
          ? req.method!
          : "OTHER",
        statusCode: res.headersSent ? res.statusCode : null,
        durationMs:
          Number(process.hrtime.bigint() - started) / 1_000_000,
        outcome,
      };

      try {
        log(Object.freeze(entry));
      } catch {
        // A synchronous logging failure must not break the request.
        // Do not print the error: it could contain sensitive data.
      }
    }

    function onFinish(): void {
      complete("finished");
    }

    function onClose(): void {
      complete(res.writableFinished ? "finished" : "aborted");
    }

    res.once("finish", onFinish);
    res.once("close", onClose);
    next();
  };
}
