// config.ts
export interface Config {
  readonly http: {
    readonly host: string;
    readonly port: number;
  };
  readonly database: {
    readonly url: string;
    readonly token: string;
  };
  readonly api: {
    readonly baseUrl: string;
    readonly token: string;
  };
}

export function loadConfig(
  env: Readonly<Record<string, string | undefined>> = process.env,
): Config {
  function required(name: string): string {
    const value = env[name];
    if (value === undefined || value.trim() === "") {
      throw new Error(`${name} is required`);
    }
    return value;
  }

  function endpoint(name: string, protocols: readonly string[]): string {
    const value = required(name);
    let parsed: URL;

    try {
      parsed = new URL(value);
    } catch {
      // Do not include the value or the parser's original exception.
      throw new Error(`${name} must be a valid absolute URL`);
    }

    if (
      !protocols.includes(parsed.protocol) ||
      !parsed.hostname ||
      parsed.username ||
      parsed.password ||
      parsed.search ||
      parsed.hash
    ) {
      throw new Error(
        `${name} has an unsupported scheme, missing host, ` +
        "or embedded credentials, query, or fragment",
      );
    }

    return value;
  }

  function token(name: string): string {
    const value = required(name);
    // Suitable for an HTTP Authorization header; no whitespace/control bytes.
    if (!/^[\x21-\x7e]+$/.test(value)) {
      throw new Error(`${name} must contain only visible ASCII characters`);
    }
    return value;
  }

  const portText = env.PORT ?? "3000";
  if (!/^[0-9]+$/.test(portText)) {
    throw new Error("PORT must be an integer between 1 and 65535");
  }

  const port = Number(portText);
  if (!Number.isSafeInteger(port) || port < 1 || port > 65535) {
    throw new Error("PORT must be an integer between 1 and 65535");
  }

  return Object.freeze({
    http: Object.freeze({
      host: env.HOST === undefined ? "0.0.0.0" : required("HOST"),
      port,
    }),
    database: Object.freeze({
      // PostgreSQL assumed; adjust schemes for your database driver.
      url: endpoint("DATABASE_URL", ["postgres:", "postgresql:"]),
      token: token("DATABASE_TOKEN"),
    }),
    api: Object.freeze({
      baseUrl: endpoint("API_BASE_URL", ["https:"]),
      token: token("API_TOKEN"),
    }),
  });
}
