The middleware logs an internally generated request ID, completion status, and duration. It deliberately avoids raw paths because path segments can also contain secrets or personal data.

```ts
// request-logging.ts
import { randomUUID } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";

interface RequestLog {
  event: "http_request";
  requestId: string;
  method: string;
  outcome: "finished" | "aborted";
  statusCode: number | null;
  durationMs: number;
}

type LogWriter = (entry: RequestLog) => void;

const standardMethods = new Set([
  "GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS", "CONNECT", "TRACE",
]);

const writeStdout: LogWriter = (entry) => {
  process.stdout.write(`${JSON.stringify(entry)}\n`);
};

export function requestLogging(write: LogWriter = writeStdout) {
  return (
    req: IncomingMessage,
    res: ServerResponse,
    next: () => void,
  ): void => {
    const requestId = randomUUID();
    const started = process.hrtime.bigint();
    const method = standardMethods.has(req.method ?? "")
      ? req.method!
      : "OTHER";

    // Do not trust or echo a client-supplied request ID.
    res.setHeader("X-Request-Id", requestId);

    let recorded = false;

    function record(outcome: RequestLog["outcome"]): void {
      if (recorded) return;
      recorded = true;

      res.off("finish", onFinish);
      res.off("close", onClose);

      const entry: RequestLog = {
        event: "http_request",
        requestId,
        method,
        outcome,
        statusCode:
          outcome === "finished" || res.headersSent ? res.statusCode : null,
        durationMs:
          Number(process.hrtime.bigint() - started) / 1_000_000,
      };

      try {
        write(entry);
      } catch {
        // A synchronous logging failure must not break request handling.
        // No fallback dump of the request, configuration, or exception.
      }
    }

    function onFinish(): void {
      record("finished");
    }

    function onClose(): void {
      record(res.writableFinished ? "finished" : "aborted");
    }

    res.once("finish", onFinish);
    res.once("close", onClose);
    next();
  };
}
```

