Make the business rules explicit. This example assumes:

- All amounts use one currency and integer cents.
- The highest qualifying tier applies, based on the original subtotal.
- One coupon applies after the tier discount.
- Discounts cannot reduce the balance below zero.
- Tax applies to the discounted balance; each percentage calculation rounds half up.

These are example policies; change them to match your requirements.

```ts
// order-total.ts
type Tier = Readonly<{
  minimumCents: bigint;
  discountBps: bigint; // 1,000 basis points = 10%
}>;

type Coupon =
  | Readonly<{ kind: "fixed"; amountCents: bigint }>
  | Readonly<{ kind: "percent"; discountBps: bigint }>;

type Input = Readonly<{
  lines: readonly Readonly<{
    unitPriceCents: bigint;
    quantity: bigint;
  }>[];
  tiers: readonly Tier[];
  coupon?: Coupon;
  taxBps: bigint;
}>;

function nonNegative(value: bigint): void {
  if (value < 0n) throw new RangeError("Value must be non-negative");
}

function validRate(bps: bigint): void {
  if (bps < 0n || bps > 10_000n) {
    throw new RangeError("Rate must be between 0 and 10,000 bps");
  }
}

function percentage(amount: bigint, bps: bigint): bigint {
  // Exact integer arithmetic, rounded half up to the nearest cent.
  return (amount * bps + 5_000n) / 10_000n;
}

export function calculateTotal(input: Input) {
  validRate(input.taxBps);

  const subtotalCents = input.lines.reduce((sum, line) => {
    nonNegative(line.unitPriceCents);
    if (line.quantity <= 0n) {
      throw new RangeError("Quantity must be positive");
    }
    return sum + line.unitPriceCents * line.quantity;
  }, 0n);

  let tierBps = 0n;
  let qualifyingMinimum = -1n;
  const thresholds = new Set<bigint>();

  for (const tier of input.tiers) {
    nonNegative(tier.minimumCents);
    validRate(tier.discountBps);
    if (thresholds.has(tier.minimumCents)) {
      throw new RangeError("Duplicate tier threshold");
    }
    thresholds.add(tier.minimumCents);

    if (
      subtotalCents >= tier.minimumCents &&
      tier.minimumCents > qualifyingMinimum
    ) {
      qualifyingMinimum = tier.minimumCents;
      tierBps = tier.discountBps;
    }
  }

  const tierDiscountCents = percentage(subtotalCents, tierBps);
  const afterTierCents = subtotalCents - tierDiscountCents;

  let couponDiscountCents = 0n;
  if (input.coupon?.kind === "fixed") {
    nonNegative(input.coupon.amountCents);
    couponDiscountCents =
      input.coupon.amountCents < afterTierCents
        ? input.coupon.amountCents
        : afterTierCents;
  } else if (input.coupon?.kind === "percent") {
    validRate(input.coupon.discountBps);
    couponDiscountCents = percentage(
      afterTierCents,
      input.coupon.discountBps,
    );
  }

  const taxableCents = afterTierCents - couponDiscountCents;
  const taxCents = percentage(taxableCents, input.taxBps);

  return {
    subtotalCents,
    tierDiscountCents,
    couponDiscountCents,
    taxableCents,
    taxCents,
    totalCents: taxableCents + taxCents,
  };
}
```

