For this example, the rules are explicit:

- Select the highest tier whose threshold meets the original subtotal.
- Apply the tier discount, then one coupon.
- Cap fixed coupons at the remaining subtotal.
- Calculate tax afterward, rounding each percentage calculation half up.

These are example business rules; adjust tax treatment and rounding to your actual requirements.

```js
// pricing.mjs
// Money uses bigint minor units: 1000n means $10.00 for USD.
// Rates use basis points: 825 means 8.25%.

function validateMoney(value) {
  if (typeof value !== "bigint" || value < 0n) {
    throw new RangeError("Money must be a nonnegative bigint");
  }
}

function validateRate(value) {
  if (!Number.isInteger(value) || value < 0 || value > 10_000) {
    throw new RangeError("Rate must be an integer from 0 to 10000");
  }
}

function percentage(amount, bps) {
  return (amount * BigInt(bps) + 5_000n) / 10_000n;
}

export function calculateTotal({
  subtotal,
  tiers = [],
  coupon = null,
  taxBps,
}) {
  validateMoney(subtotal);
  validateRate(taxBps);

  let tier = null;
  const thresholds = new Set();

  for (const candidate of tiers) {
    validateMoney(candidate.minimum);
    validateRate(candidate.discountBps);

    if (thresholds.has(candidate.minimum)) {
      throw new RangeError("Duplicate tier threshold");
    }
    thresholds.add(candidate.minimum);

    if (
      candidate.minimum <= subtotal &&
      (!tier || candidate.minimum > tier.minimum)
    ) {
      tier = candidate;
    }
  }

  const tierDiscount = percentage(subtotal, tier?.discountBps ?? 0);
  const afterTier = subtotal - tierDiscount;
  let couponDiscount = 0n;

  if (coupon !== null) {
    switch (coupon.kind) {
      case "percent":
        validateRate(coupon.bps);
        couponDiscount = percentage(afterTier, coupon.bps);
        break;

      case "fixed":
        validateMoney(coupon.amount);
        couponDiscount =
          coupon.amount > afterTier ? afterTier : coupon.amount;
        break;

      default:
        throw new TypeError("Unknown coupon kind");
    }
  }

  const taxableSubtotal = afterTier - couponDiscount;
  const tax = percentage(taxableSubtotal, taxBps);

  return {
    subtotal,
    tierDiscount,
    couponDiscount,
    taxableSubtotal,
    tax,
    total: taxableSubtotal + tax,
  };
}
```

